async def act(page):
    """
    Filter the Orders grid to show cancelled orders and return the customer
    name from the most recent cancelled order (first data row after filtering).

    Continues from the current page state (does not navigate away).
    """
    import asyncio

    # Helper to safely read inner_text from a locator
    async def safe_inner_text(locator):
        try:
            txt = await locator.inner_text()
            return (txt or "").strip()
        except Exception:
            return ""

    # Reason about KB helpers: none of the provided knowledge-base helpers
    # specifically filter the Sales > Orders grid by Status and return a
    # most-recent cancelled order. They focus on the Dashboard Last Orders
    # widget or exporting snapshots. Therefore we do not call any KB helper
    # and perform the grid interactions directly.

    # Short sleep to allow any ongoing UI changes to settle
    await asyncio.sleep(0.5)

    # Locate the main orders table by finding a table that has a header cell
    # named 'Order #'
    tables = page.get_by_role('table')
    orders_table = None
    if await tables.count() > 0:
        tcount = await tables.count()
        for i in range(tcount):
            t = tables.nth(i)
            try:
                # Look for a header cell labelled 'Order #' inside this table
                if await t.get_by_role('cell', name='Order #').count() > 0:
                    orders_table = t
                    break
            except Exception:
                # ignore transient issues
                continue

    if orders_table is None:
        # Can't find orders table; nothing more we can do from here
        print("")
        return ""

    # Find a combobox inside that table whose options include a label
    # containing the substring 'cancel' (case-insensitive).
    status_combobox = None
    matching_option_label = None
    comboboxes = orders_table.get_by_role('combobox')
    if await comboboxes.count() > 0:
        cb_count = await comboboxes.count()
        for ci in range(cb_count):
            cb = comboboxes.nth(ci)
            # enumerate options
            try:
                opts = cb.get_by_role('option')
            except Exception:
                opts = None
            if not opts:
                continue
            try:
                opt_count = await opts.count()
            except Exception:
                opt_count = 0
            for oi in range(opt_count):
                opt = opts.nth(oi)
                text = await safe_inner_text(opt)
                if 'cancel' in text.lower():
                    status_combobox = cb
                    matching_option_label = text
                    break
            if status_combobox:
                break

    # If a status combobox with a cancel option was found, select it and apply
    if status_combobox and matching_option_label:
        try:
            # prefer selecting by the exact visible label read from the DOM
            await status_combobox.select_option(label=matching_option_label)
        except Exception:
            # narrow fallback: try to find the matching option's value attribute
            try:
                opts = status_combobox.get_by_role('option')
                if await opts.count() > 0:
                    for oi in range(await opts.count()):
                        opt = opts.nth(oi)
                        text = await safe_inner_text(opt)
                        if 'cancel' in text.lower():
                            val = await opt.get_attribute('value')
                            if val is not None:
                                await status_combobox.select_option(value=val)
                                break
            except Exception:
                pass

        # Click the Search button to apply the filter. Use a broad locator for Search
        # but prefer the button exposed with role/button name 'Search'.
        try:
            search_btns = page.get_by_role('button', name='Search')
            if await search_btns.count() > 0:
                await search_btns.nth(0).click()
            else:
                # fallback: click any button whose visible text contains 'search'
                all_buttons = page.get_by_role('button')
                if await all_buttons.count() > 0:
                    for bi in range(await all_buttons.count()):
                        b = all_buttons.nth(bi)
                        btxt = await safe_inner_text(b)
                        if 'search' in btxt.lower():
                            await b.click()
                            break
        except Exception:
            # clicking search failed; we'll still attempt to read the table
            pass

        # allow time for grid to refresh
        await asyncio.sleep(1)

    # Re-locate the orders table (in case it re-rendered)
    tables = page.get_by_role('table')
    if await tables.count() > 0:
        for i in range(await tables.count()):
            t = tables.nth(i)
            try:
                if await t.get_by_role('cell', name='Order #').count() > 0:
                    orders_table = t
                    break
            except Exception:
                continue

    # Find the first data row (heuristic: a row containing a 'View' link)
    rows = orders_table.get_by_role('row')
    customer_name = ''
    if await rows.count() > 0:
        for ri in range(await rows.count()):
            row = rows.nth(ri)
            try:
                # skip header/filter rows that mention 'Order #' or 'Any'
                rtxt = await safe_inner_text(row)
                if not rtxt:
                    continue
                if 'Order #' in rtxt or rtxt.strip().startswith('Page') or 'Select Visible' in rtxt or rtxt.strip().startswith('Any'):
                    continue
                # If this row has a View link it's a data row
                if await row.get_by_role('link', name='View').count() == 0:
                    # if no View link, it might still be a data row; use other heuristics
                    # prefer rows that start with an order number pattern like '000000'
                    if '000000' not in rtxt:
                        continue
                # This looks like a data row. Extract cells and pick the Bill to Name cell (5th data cell)
                cells = row.get_by_role('cell')
                if await cells.count() > 4:
                    # cell index 4 corresponds to 'Bill to Name' in the grid
                    try:
                        ctext = (await cells.nth(4).inner_text() or '').strip()
                        if ctext:
                            customer_name = ctext
                            break
                    except Exception:
                        pass
                # Fallback: attempt to find a cell that looks like a person name
                if await cells.count() > 0:
                    for ci in range(await cells.count()):
                        try:
                            ctext = (await cells.nth(ci).inner_text() or '').strip()
                        except Exception:
                            ctext = ''
                        if ctext and any(ch.isalpha() for ch in ctext) and ' ' in ctext:
                            customer_name = ctext
                            break
                    if customer_name:
                        break
                # Last resort: parse the row text and pick a token that looks like a name
                tokens = rtxt.split()
                for tok in tokens:
                    if any(ch.isalpha() for ch in tok) and len(tok) > 1:
                        # try to build two-token name if possible
                        idx = tokens.index(tok)
                        if idx + 1 < len(tokens):
                            candidate = tok + ' ' + tokens[idx + 1]
                            customer_name = candidate
                        else:
                            customer_name = tok
                        break

                if customer_name:
                    break
            except Exception:
                continue

    # Print and return the found name (or empty string if not found)
    print(customer_name)
    return customer_name

